go

package main

import ("fmt")
       ("math")

func main() {
    var x float64
    // Membaca masukan satu bilangan riil untuk x
    fmt.Scan(&x)

    // Menghitung nilai pembilang dan penyebut
    pembilang := math.Pow(x, 3) + (3 * x)
    penyebut := math.Pow(x, 4) - (3 * math.Pow(x, 2)) + 4

    // Menghitung nilai f(x)
    fx := pembilang / penyebut

    // Menampilkan keluaran berupa nilai f(x)
    fmt.Println(fx)
}

