program HitungPecahanKembalian

kamus
    kembalian : integer    { Total uang kembalian }
    sepuluhRibu : integer  { Jumlah lembar Rp 10.000 }
    limaRibu    : integer  { Jumlah lembar Rp 5.000 }
    satuRibu    : integer  { Jumlah lembar Rp 1.000 }
    sisa        : integer  { Sisa uang kembalian setelah diambil pecahan terbesar }

algoritma
    input(kembalian)

    { Hitung pecahan 10.000 }
    sepuluhRibu <- kembalian div 10000
    sisa <- kembalian mod 10000

    { Hitung pecahan 5.000 dari sisa kembalian }
    limaRibu <- sisa div 5000
    sisa <- sisa mod 5000

    { Hitung pecahan 1.000 dari sisa terakhir }
    satuRibu <- sisa div 1000

    output(sepuluhRibu, limaRibu, satuRibu)

endprogram

