program Balikbilangan
kamus
   N     : integer    { Bilangan tiga digit masukan }
    d1    : integer    { Digit satuan }
    d2    : integer    { Digit puluhan }
    d3    : integer    { Digit ratusan }
    hasil : integer    { Bilangan setelah dibalik }
algoritma
    input(N)

    d1 <- N mod 10
    d2 <- (N div 10) mod 10
    d3 <- N div 100

    hasil <- (d1 * 100) + (d2 * 10) + d3

    output(hasil)

endprogram

