program CekFaktor

kamus
    x : integer    { Bilangan pertama (lebih besar) }
    y : integer    { Bilangan kedua (pembagi) }
    hasil : integer    { Output: 1 jika y faktor dari x, 0 jika bukan }

algoritma
    input(x, y)

    { Jika x habis dibagi y, x mod y akan bernilai 0. }
    { Menggunakan ekspresi kondisi/relasional untuk menghasilkan 1 (True) atau 0 (False). }
    hasil <- (x mod y = 0)

    output(hasil)

endprogram

