program Cekfaktor
kamus
    x     : integer    { Bilangan pertama }
    y     : integer    { Bilangan kedua }
    sisa  : integer    { Sisa hasil bagi x mod y }
    hasil : integer    { 1 jika y faktor dari x, 0 jika bukan }

algoritma
    input(x, y)

    sisa <- x mod y

    { Mengubah nilai sisa > 0 menjadi 1, dan sisa = 0 tetap 0 }
    { Lalu dibalik nilainya menggunakan 1 - (...) }
    hasil <- 1 - ((sisa + y - 1) div y)

    output(hasil)

endprogram

