program CekNegatif

kamus
    N     : integer    { Bilangan bulat masukan 32-bit }
    hasil : integer    { Output: 1 jika negatif, 0 jika tidak }

algoritma
    input(N)

    { Dalam format 32-bit signed integer (Two's Complement): }
    { Bit paling kiri (bit ke-31 / MSB) adalah sign bit: }
    { - Nilai 1 menandakan bilangan negatif }
    { - Nilai 0 menandakan bilangan non-negatif (nol/positif) }
    { Menggeser bit ke kanan sebanyak 31 posisi dengan 'logical shift' }
    { atau melakukan pergeseran aritmatika lalu dikandandkan dengan 1 }

    hasil <- (N bit-shift-right 31) bit-and 1

    output(hasil)

endprogram

Student_Code:
program Ceknegatif
kamus
    N     : integer    { Bilangan bulat masukan 32-bit }
    hasil : integer    { Output: 1 jika negatif, 0 jika tidak }

algoritma
    input(N)

    { Karena rentang N adalah -2147483648 s.d. 2147483647 }
    { N + 2147483648 akan bernilai < 2147483648 jika N negatif }
    { dan >= 2147483648 jika N non-negatif }
    hasil <- 1 - ((N + 2147483648) div 2147483648)

    output(hasil)

endprogram

