program NilaiMutlak32Bit

kamus
    N     : integer    { Bilangan bulat masukan (32-bit) }
    mask  : integer    { Topeng bitwise dari bit tanda/sign bit }
    hasil : integer    { Nilai mutlak dari N }

algoritma
    read(N)

    { Menggeser bit sebanyak 31 posisi ke kanan untuk mengambil bit tanda (sign bit). }
    { Jika N positif, mask = 0 (semua bit 0). }
    { Jika N negatif, mask = -1 (semua bit 1 / dua komplemen). }
    mask <- N bit-shift-right 31

    { Menggunakan properti XOR dan pengurangan: }
    { Jika N >= 0: (N XOR 0) - 0 = N }
    { Jika N < 0 : (N XOR -1) - (-1) = NOT(N) + 1 = -N }
    hasil <- (N bit-xor mask) - mask

    write(hasil)

endprogram

