program Menyisipkanangkatengah

kamus
    bilangan : integer    { Bilangan empat digit masukan, contoh: 1234 }
    disisip  : integer    { Bilangan satu digit yang akan disisipkan, contoh: 5 }
    depan    : integer    { Dua digit bagian depan, contoh: 12 }
    belakang : integer    { Dua digit bagian belakang, contoh: 34 }
    hasil    : integer    { Bilangan lima digit hasil penggabungan }

algoritma
    input(bilangan, disisip)

    { Mengambil 2 digit depan dengan membagi bulat 100 }
    depan <- bilangan div 100

    { Mengambil 2 digit belakang dengan sisa bagi (mod) 100 }
    belakang <- bilangan mod 100

    { Menyusun kembali: (depan * 1000) + (disisip * 100) + belakang }
    hasil <- (depan * 1000) + (disisip * 100) + belakang

    output(hasil)

endprogram

