program Tukartigavariabel

kamus
    x    : integer    { Variabel x }
    y    : integer    { Variabel y }
    z    : integer    { Variabel z }
    temp : integer    { Variabel penampung sementara }

algoritma
    input(x, y, z)

    { Menyimpan nilai asal y ke variabel sementara }
    temp <- y

    { Variabel y diisi nilai asal x }
    y <- x

    { Variabel x diisi nilai asal z }
    x <- z

    { Variabel z diisi nilai asal y (yang tersimpan di temp) }
    z <- temp

    output(x, y, z)

endprogram

